CREATE TABLE IF NOT EXISTS plot_no_action_effects (
  no_action_effect_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  plot_id BIGINT UNSIGNED NOT NULL,
  event_code VARCHAR(120) NOT NULL,
  role_code VARCHAR(100) NOT NULL,
  effect_scope ENUM('FACTOR','STAT','LOCATION','KNOWLEDGE','WORLD_STATE') NOT NULL,
  target_code VARCHAR(190) NOT NULL,
  delta_value INT NULL,
  set_value VARCHAR(500) NULL,
  detail_text TEXT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  KEY idx_pnae(plot_id,event_code,role_code),
  CONSTRAINT fk_pnae_plot FOREIGN KEY(plot_id) REFERENCES plots(plot_id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @plot_id=(SELECT plot_id FROM plots WHERE code='CONCEALED_FAILURE' LIMIT 1);

-- Keep individual first aid from unrealistically making the whole resort much safer.
UPDATE plot_option_effects poe
JOIN plot_decision_template_options o ON o.template_option_id=poe.template_option_id
JOIN plot_decision_templates t ON t.template_id=o.template_id
SET poe.delta_value=2
WHERE t.plot_id=@plot_id AND t.event_code='WALL_SHIFT' AND t.role_code='LEILA' AND o.option_code='STABILIZE_GUEST' AND poe.effect_scope='FACTOR' AND poe.target_code='SAFETY';
UPDATE plot_option_effects poe
JOIN plot_decision_template_options o ON o.template_option_id=poe.template_option_id
JOIN plot_decision_templates t ON t.template_id=o.template_id
SET poe.delta_value=4
WHERE t.plot_id=@plot_id AND t.event_code='WALL_SHIFT' AND t.role_code='WREN' AND o.option_code='HELP_LEILA' AND poe.effect_scope='FACTOR' AND poe.target_code='SAFETY';
SET @o=(SELECT o.template_option_id FROM plot_decision_template_options o JOIN plot_decision_templates t ON t.template_id=o.template_id WHERE t.plot_id=@plot_id AND t.event_code='WALL_SHIFT' AND t.role_code='LEILA' AND o.option_code='STABILIZE_GUEST' LIMIT 1);
SELECT @o,'WORLD_STATE','GUEST_STATUS','STABILIZED','The injured guest is stabilized but still needs help to evacuate.',5 FROM DUAL
WHERE @o IS NOT NULL AND NOT EXISTS(SELECT 1 FROM plot_option_effects WHERE template_option_id=@o AND effect_scope='WORLD_STATE' AND target_code='GUEST_STATUS');

-- Cycle 2: evidence conflict.


SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REPORT_MISSING' AND role_code='KELLAN');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='TELL_ALDEN_ALARM');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='HELP_LEILA_NOW');

SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REPORT_MISSING' AND role_code='NIKO');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='CHALLENGE_CERTIFICATE');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='TAKE_EVAC_COMMAND');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='BACK_FARAH');

SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REPORT_MISSING' AND role_code='WREN');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='TELL_NIKO_RED_STAMP');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='MOVE_GUEST');
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='CHECK_ROUTE');

