SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REAR_EXIT' AND role_code='KELLAN');INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,result_text,sort_order) VALUES(@t,'BLOCK_WITH_INFO','Call out Farah’s alarm-bypass question and force the exit confrontation into the open.','You use your private observation at the moment it can most constrain Farah.',1),(@t,'FOLLOW_EXIT','Follow Farah and become a witness to whatever she does with the records.','You stay with Farah rather than letting the evidence trail disappear.',2),(@t,'FINAL_RESCUE_K','Leave the confrontation and help finish the injured guest’s evacuation.','You choose the rescue over the confrontation.',3);
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='BLOCK_WITH_INFO');INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES(@o,'FACTOR','SUSPICION',14,NULL,'Kellan makes the alarm-bypass detail public at the exit.',1),(@o,'FACTOR','CONTROL',-8,NULL,'Farah loses room to frame her movement as routine.',2),(@o,'WORLD_STATE','ALARM_INFO_PUBLIC',NULL,'YES','The alarm-bypass question is now common knowledge.',3);
