SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REAR_EXIT' AND role_code='NIKO');INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,result_text,sort_order) VALUES(@t,'STOP_FARAH','Use your authority to stop Farah at the rear exit and demand the records stay.','You directly oppose Farah and prevent an uncontested exit.',1),(@t,'LET_FARAH_GO','Allow Farah through so the evacuation is not delayed.','You choose operational flow over confrontation and let Farah leave.',2),(@t,'FINAL_EVAC_COMMAND','Turn away from Farah and personally finish the evacuation command.','You make guest safety your final priority.',3);
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='STOP_FARAH');INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES(@o,'FACTOR','CONTROL',-15,NULL,'Niko uses formal authority against Farah.',1),(@o,'FACTOR','EVIDENCE',8,NULL,'The records cannot leave uncontested.',2),(@o,'STAT','LOYALTY',-15,NULL,'Niko decisively breaks with Farah.',3),(@o,'WORLD_STATE','FARAH_EXIT_STATUS',NULL,'BLOCKED','Farah is stopped at the rear exit.',4);
