SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REAR_EXIT' AND role_code='FARAH');INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES(@t,'LEAVE_WITH_RECORDS','Try to leave through the rear exit with whatever records you control.',50,'Self-preservation strongly favors physical separation from the evidence fight.','Farah moves to leave Bellweather through the rear exit.',1),(@t,'DESTROY_LEVERAGE','Try to make the remaining evidence unusable before anyone can secure it.','30','If escape is uncertain, reducing evidence may be safer.','Farah focuses on making the remaining evidence harder to use.',2),(@t,'STAY_AND_DENY','Remain and insist the group is misreading an emergency as a conspiracy.','20','Manipulation may still preserve authority if the group is divided.','Farah stays and makes a final public denial.',3);
