SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REAR_EXIT' AND role_code='ALDEN');INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES(@t,'HAND_OFF_EVIDENCE','Give the strongest surviving evidence to another character before Farah can isolate it.','50','Redundancy is safest at the climax.','Alden transfers the evidence so it no longer depends on him alone.',1),(@t,'BLOCK_FARAH_NPC','Move to the rear exit and confront Farah directly.','30','The final chance to preserve proof may require confrontation.','Alden moves to stop Farah leaving uncontested.',2),(@t,'CALL_AUTHORITIES','Use the remaining connection to send the evidence summary outside Bellweather.','20','Externalizing the evidence makes physical control less important.','Alden sends the core evidence summary beyond the resort.',3);
