SET @t=(SELECT template_id FROM plot_decision_templates WHERE plot_id=@plot_id AND event_code='REAR_EXIT' AND role_code='LEILA');INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES(@t,'COMPLETE_EVAC_NPC','Finish moving the injured guest toward the west point with whoever is available.','65','The guest’s safety is Leila’s overriding goal.','Leila commits to getting the injured guest clear of the east side.',1),(@t,'CALL_FOR_FINAL_HELP','Refuse to move unsafely and call again for another helper.','25','Moving without enough help could worsen the injury.','Leila stops and demands one more person before moving.',2),(@t,'SHELTER_FINAL','Keep the guest sheltered where they are through the immediate movement.','10','If the route looks worse than the room, sheltering may be the least bad option.','Leila keeps the guest sheltered in place.',3);
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='COMPLETE_EVAC_NPC');INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES(@o,'FACTOR','SAFETY',8,NULL,'Leila gets the guest moving toward safety.',1),(@o,'WORLD_STATE','GUEST_STATUS',NULL,'EVACUATED','The injured guest reaches the west evacuation point.',2);
SET @o=(SELECT template_option_id FROM plot_decision_template_options WHERE template_id=@t AND option_code='CALL_FOR_FINAL_HELP');INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,set_value,detail_text,sort_order) VALUES(@o,'WORLD_STATE','HELP_REQUEST_ACTIVE','YES','Leila still needs another helper.',1);

