INSERT IGNORE INTO plot_event_perceptions(plot_id,event_code,role_code,history_type,title,perception_text,location_after) VALUES
(@plot_id,'REPORT_MISSING','KELLAN','OBSERVED','The Office Reaction Makes Sense','The argument over Alden’s report makes Farah’s earlier interest in the unlogged service door feel less accidental. You may have information nobody else has connected yet.',NULL),
(@plot_id,'REPORT_MISSING','NIKO','EXPERIENCED','Two Certificates Cannot Both Be The Truth','Alden’s claim about a failed report conflicts directly with the passing certificate Farah showed you. Your loyalty and your operational responsibility now point in different directions.',NULL),
(@plot_id,'REPORT_MISSING','WREN','OBSERVED','The Red Stamp Matters','You remember Alden photocopying a red-stamped engineering document before dinner. The report dispute is no longer abstract to you.',NULL),
(@plot_id,'REPORT_MISSING','FARAH','EXPERIENCED','The Evidence Fight Is Public','The report has become the center of the room’s attention. Removing evidence is no longer the only problem; you must shape what people believe about it.',NULL),
(@plot_id,'REPORT_MISSING','ALDEN','EXPERIENCED','Proof Needs A Witness','Possessing or losing the report is only part of the problem. Unless someone credible understands what it means, Farah can still control the explanation.',NULL),
(@plot_id,'REPORT_MISSING','LEILA','OBSERVED','The Argument Pulls Attention Away','People are arguing about documents while the injured guest still cannot safely leave the east side without help.',NULL);
INSERT IGNORE INTO plot_decision_templates(plot_id,event_code,role_code,actor_type,prompt_text,decision_window_seconds) VALUES
(@plot_id,'REPORT_MISSING','KELLAN','PLAYER','The report conflict makes your memory about Farah and the service-door alarm newly important. What do you do?',30),
(@plot_id,'REPORT_MISSING','NIKO','PLAYER','Alden’s failed report contradicts the certificate Farah showed you. What do you do?',30),
(@plot_id,'REPORT_MISSING','WREN','PLAYER','You can connect Alden to the red-stamped report, but the injured guest still needs attention. What do you do?',30),
(@plot_id,'REPORT_MISSING','FARAH','NPC','The report dispute is now public. Choose how to protect your position.',30),
(@plot_id,'REPORT_MISSING','ALDEN','NPC','The evidence is contested. Choose how to make it survive or matter.',30),
(@plot_id,'REPORT_MISSING','LEILA','NPC','The evidence argument is drawing people away from the injured guest. What do you do?',30);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'TELL_ALDEN_ALARM','Tell Alden exactly what you heard Farah ask about the service-door alarm.',0,NULL,'You give Alden a second fact that may connect Farah to deliberate movement around the office.',1),
(@t,'WATCH_FARAH_REPORT','Keep the alarm detail private and watch how Farah reacts to the report dispute.',0,NULL,'You hold your information and watch Farah for a revealing move.',2),
(@t,'HELP_LEILA_NOW','Leave the evidence dispute and go help Leila with the injured guest.',0,NULL,'You choose the immediate human need over the evidence conflict.',3);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SUSPICION',10,NULL,'Kellan’s private observation becomes corroborating evidence.',1),(@o,'WORLD_STATE','ALARM_INFO_SHARED',NULL,'YES','Alden now knows Farah asked about bypassing the alarm log.',2);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SAFETY',5,NULL,'Kellan adds another capable person to the east-side response.',1),(@o,'LOCATION','SELF',NULL,'East Stairwell','Kellan goes to help Leila.',2),(@o,'WORLD_STATE','GUEST_HELPERS',NULL,'2','Leila now has enough help to move the guest if the route is usable.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'CHALLENGE_CERTIFICATE','Ask Farah, in front of Alden, why the certificate you saw does not match his failed report.',0,NULL,'You force the contradiction into the open instead of protecting Farah from it.',1),
(@t,'TAKE_EVAC_COMMAND','Refuse the evidence argument for now and take command of evacuation.',0,NULL,'You prioritize operational control and move people away from danger.',2),
(@t,'BACK_FARAH','Tell Alden this is not the time and publicly back Farah’s focus on evacuation.',0,NULL,'You lend Farah your credibility and postpone the evidence dispute.',3);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SUSPICION',12,'Niko publicly exposes the certificate contradiction.',1),(@o,'FACTOR','CONTROL',-8,'Farah loses some control over the explanation.',2),(@o,'STAT','LOYALTY',-10,'Niko’s loyalty weakens when he directly challenges Farah.',3);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SAFETY',8,NULL,'Niko creates an organized evacuation response.',1),(@o,'LOCATION','SELF',NULL,'Lobby Command Point','Niko takes visible command of the evacuation.',2);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,detail_text,sort_order) VALUES
(@o,'FACTOR','CONTROL',8,'Niko’s credibility reinforces Farah’s authority.',1),(@o,'FACTOR','SUSPICION',-4,'Public doubt is temporarily suppressed.',2);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'TELL_NIKO_RED_STAMP','Tell Niko you saw Alden photocopy a red-stamped engineering report before dinner.',0,NULL,'You give Niko independent reason to take Alden’s report claim seriously.',1),
(@t,'MOVE_GUEST','Stay with Leila and help prepare the injured guest for evacuation.',0,NULL,'You keep your attention on getting the injured guest out safely.',2),
(@t,'CHECK_ROUTE','Inspect the west evacuation route before anyone tries to move the injured guest.',0,NULL,'You verify whether the route can actually support an evacuation.',3);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SUSPICION',8,NULL,'Wren corroborates that a serious engineering report existed.',1),(@o,'WORLD_STATE','RED_STAMP_SHARED',NULL,'YES','Niko now knows Wren saw Alden copying a red-stamped report.',2);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SAFETY',5,NULL,'Wren remains committed to the injured guest.',1),(@o,'WORLD_STATE','GUEST_HELPERS',NULL,'2','Leila has enough help to move the guest.',2);
INSERT INTO plot_option_effects(template_option_id,effect_scope,target_code,delta_value,set_value,detail_text,sort_order) VALUES
(@o,'FACTOR','SAFETY',4,NULL,'Wren verifies the safer route.',1),(@o,'WORLD_STATE','WEST_ROUTE',NULL,'USABLE','The west route is confirmed usable for evacuation.',2);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'DISCREDIT_ALDEN','Tell the group Alden is exploiting the emergency to settle a private dispute.',40,'Manipulation can reduce the value of evidence without physically controlling it.','Farah attacks Alden’s credibility and reframes the report as a personal accusation.',1),
(@t,'PRESSURE_NIKO','Pull Niko aside and remind him that guests need visible leadership, not an investigation.',35,'Niko’s loyalty and authority can be used to suppress the dispute.','Farah pressures Niko to keep the group focused on evacuation and away from Alden.',2),
(@t,'MOVE_EVIDENCE','Use the confusion to move or further conceal whatever report material you control.',25,'Self-preservation favors making the evidence harder to recover.','Farah focuses on keeping the report beyond immediate reach.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'SHOW_NIKO','Show Niko the report or explain exactly what the failed copy said.',45,'A credible insider is the best route to making the evidence matter.','Alden brings Niko directly into the evidence dispute.',1),
(@t,'HIDE_COPY','Keep the report hidden until authorities can receive it.',35,'Caution favors preserving the evidence rather than winning the room immediately.','Alden conceals the surviving report material and avoids a public confrontation.',2),
(@t,'ACCUSE_FARAH','Publicly accuse Farah of concealing the failed inspection.',20,'Evidence focus can push Alden into direct confrontation.','Alden openly accuses Farah of hiding the structural failure.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'RECRUIT_HELPER','Interrupt the argument and demand a second person help move the injured guest.',55,'Leila knows first aid is not enough if the east side worsens.','Leila loudly calls for a second helper and forces the injured guest back into everyone’s attention.',1),
(@t,'KEEP_TREATING','Remain with the guest and continue treatment while waiting for help.',30,'Empathy favors staying physically with the injured person.','Leila continues stabilizing the guest but does not yet move them.',2),
(@t,'CHECK_WEST_ROUTE_NPC','Briefly check whether the west route is still usable.',15,'A safe evacuation requires a viable destination.','Leila verifies the west route before attempting movement.',3);
INSERT IGNORE INTO plot_event_perceptions(plot_id,event_code,role_code,history_type,title,perception_text,location_after) VALUES
(@plot_id,'PRESSURE_RISE','KELLAN','EXPERIENCED','The Room Has Split Into Priorities','The emergency is no longer one problem. Evidence, evacuation and Farah’s authority are pulling people in different directions.',NULL),
(@plot_id,'PRESSURE_RISE','NIKO','EXPERIENCED','Everyone Wants Your Authority','Farah, Alden and the evacuation effort all need something different from you. Whatever you legitimize now will shape the rest of the night.',NULL),
(@plot_id,'PRESSURE_RISE','WREN','EXPERIENCED','The East Side Is Running Out Of Time','The injured guest and the unstable east side remain linked. Delay is becoming a physical choice, not merely an investigative one.',NULL),
(@plot_id,'PRESSURE_RISE','FARAH','EXPERIENCED','Control Is Becoming Fragile','The group has had time to compare what they know. Your next move must protect either your authority, the evidence, or your route out.',NULL),
(@plot_id,'PRESSURE_RISE','ALDEN','EXPERIENCED','Evidence Alone May Not Be Enough','The group is under pressure and may accept the easiest explanation unless you turn proof into action.',NULL),
(@plot_id,'PRESSURE_RISE','LEILA','EXPERIENCED','The Guest Still Has To Leave','Treatment buys time, but the injured guest cannot remain in the east wing indefinitely.',NULL);
INSERT IGNORE INTO plot_decision_templates(plot_id,event_code,role_code,actor_type,prompt_text,decision_window_seconds) VALUES
(@plot_id,'PRESSURE_RISE','KELLAN','PLAYER','The group is splitting between evidence and evacuation. Where do you put your influence?',35),
(@plot_id,'PRESSURE_RISE','NIKO','PLAYER','Your authority can now materially change either safety or the evidence conflict. What do you do?',35),
(@plot_id,'PRESSURE_RISE','WREN','PLAYER','The east side is becoming less forgiving. What do you commit to?',35),
(@plot_id,'PRESSURE_RISE','FARAH','NPC','Your control is under pressure. Choose the next move that best protects you.',30),
(@plot_id,'PRESSURE_RISE','ALDEN','NPC','The report conflict must become actionable before the climax. What do you do?',30),
(@plot_id,'PRESSURE_RISE','LEILA','NPC','Treatment is not evacuation. What do you do next?',30);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,result_text,sort_order) VALUES
(@t,'SHARE_PUBLICLY','Tell the group about Farah’s alarm-bypass question.','You make your private observation common knowledge.',1),(@t,'GUARD_EVIDENCE','Go to whoever currently controls the report and stay with the evidence.','You make yourself a witness to what happens to the report next.',2),(@t,'JOIN_RESCUE','Go to the east stairwell and help complete the evacuation of the injured guest.','You leave the evidence dispute and commit to the rescue.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,result_text,sort_order) VALUES
(@t,'SIDE_WITH_EVIDENCE','Tell Farah the report dispute must be preserved for authorities.','You put your operational authority behind preserving the evidence.',1),(@t,'ORDER_FULL_EVAC','Order everyone toward the west evacuation point immediately.','You make physical safety the non-negotiable priority.',2),(@t,'KEEP_FARAH_IN_CHARGE','Continue supporting Farah as the visible crisis leader.','You preserve Farah’s authority to avoid splintering the response.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,result_text,sort_order) VALUES
(@t,'EVAC_GUEST','Commit to moving the injured guest toward the west route.','You turn stabilization into an evacuation attempt.',1),(@t,'VERIFY_HAZARD','Recheck the east-side movement and warn everyone how little time remains.','You focus on the physical clock driving the crisis.',2),(@t,'CARRY_EVIDENCE_INFO','Go to Niko with everything you know about Alden’s red-stamped report.','You bring your independent observation into the evidence conflict.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'PREPARE_EXIT','Move toward the rear exit while keeping the records case close.',40,'High self-preservation makes an exit increasingly attractive as suspicion grows.','Farah begins positioning herself near the rear exit.',1),(@t,'RALLY_GUESTS','Use the worsening storm to argue that investigation is endangering everyone.',35,'Manipulation is strongest when fear can be redirected.','Farah uses the physical danger to reclaim attention and authority.',2),(@t,'PRESSURE_ALDEN','Privately warn Alden that public accusations could destroy the resort and everyone’s jobs.','25','Pressure may make Alden hesitate without creating another public scene.','Farah tries to make Alden doubt the cost of continuing.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'DUPLICATE_EVIDENCE','Create or separate another copy of the evidence.',45,'Evidence focus favors redundancy before the final confrontation.','Alden makes the surviving evidence harder for one person to erase.',1),(@t,'FIND_WITNESS','Find a second person willing to verify what the report says.',35,'A witness makes the document harder to dismiss.','Alden seeks another person to independently understand the failed report.',2),(@t,'CONFRONT_NOW','Force Farah into a direct public confrontation now.',20,'Pressure can overcome Alden’s caution.','Alden brings the concealment accusation directly to Farah.',3);
INSERT IGNORE INTO plot_decision_template_options(template_id,option_code,label,npc_weight,rationale_text,result_text,sort_order) VALUES
(@t,'MOVE_WITH_HELP','Begin moving the injured guest if enough help is present.',55,'Leila’s urgency now favors evacuation over continued treatment.','Leila begins moving the injured guest toward the west side with whoever is available.',1),(@t,'DEMAND_HELP_PUBLIC','Stop the room and explicitly demand another helper.','30','If help has not arrived, social pressure may be necessary.','Leila shouts that the injured guest cannot remain in the east wing.',2),(@t,'SHELTER_IN_PLACE','Keep the guest where they are until the route is certain.','15','Caution about movement can briefly outweigh urgency.','Leila keeps the guest stabilized in place while watching the route.',3);
INSERT IGNORE INTO plot_event_perceptions(plot_id,event_code,role_code,history_type,title,perception_text,location_after) VALUES
(@plot_id,'REAR_EXIT','KELLAN','OBSERVED','The Exit Turns Observation Into A Choice','Farah is close enough to the rear exit that watching her is no longer neutral. What you know about the alarm may matter only if you use it.',NULL),
(@plot_id,'REAR_EXIT','NIKO','EXPERIENCED','Authority Has Become Personal','The crisis has narrowed to a direct question: who controls the evidence, who controls the exit, and whether you will use your authority against Farah.',NULL),
(@plot_id,'REAR_EXIT','WREN','EXPERIENCED','The Physical Clock Reaches The Conflict','The east-side hazard and the evidence confrontation are peaking at the same time. You cannot personally solve both.',NULL),
(@plot_id,'REAR_EXIT','FARAH','EXPERIENCED','The Last Clean Exit Is Closing','You are running out of time to preserve both your freedom and control of the story.',NULL),
(@plot_id,'REAR_EXIT','ALDEN','EXPERIENCED','Proof Must Survive The Exit','If Farah leaves with the strongest remaining evidence or without being challenged, the story of the night may harden around her version.',NULL),
(@plot_id,'REAR_EXIT','LEILA','EXPERIENCED','The East Wing Cannot Wait','The injured guest’s fate now depends on whether enough help and a usable route were created earlier.',NULL);
INSERT IGNORE INTO plot_decision_templates(plot_id,event_code,role_code,actor_type,prompt_text,decision_window_seconds) VALUES
(@plot_id,'REAR_EXIT','KELLAN','PLAYER','Farah is near the rear exit as the evidence dispute peaks. What do you do?',30),(@plot_id,'REAR_EXIT','NIKO','PLAYER','Your authority can now stop, enable, or redirect Farah. What do you do?',30),(@plot_id,'REAR_EXIT','WREN','PLAYER','The rescue and evidence conflict peak together. Where do you commit?',30),(@plot_id,'REAR_EXIT','FARAH','NPC','Your position is collapsing toward a final confrontation. Choose your move.',30),(@plot_id,'REAR_EXIT','ALDEN','NPC','The evidence must survive the final confrontation. What do you do?',30),(@plot_id,'REAR_EXIT','LEILA','NPC','The injured guest must either reach safety or remain exposed. What do you do?',30);
